window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0f592005afa03dac"]={"versions": [{"id": "FIG-0f592005afa03dac", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationslayout (ECUC Parameter Definition) kombiniert aus tabellarischer Moduldefinition und UML-Klassendiagramm für das BSW-Modul <code>MemIf</code> (Memory Abstraction Interface) gemäß Spezifikationselement <code>ECUC_MemIf_00025</code>. Das Diagramm definiert die statische Metamodell-Struktur des Moduls innerhalb des AUTOSAR-Konfigurationsframeworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in eine tabellarische Metadaten-Übersicht und ein metamodellbasiertes Klassendiagramm:</p>\n<ul class=\"fig-list\"><li><strong>Moduldefinition (<code>MemIf: EcucModuleDef</code>)</strong>: Bildet den Wurzelknoten mit der Multiplizität 0..1 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Unterstützte Konfigurationsvariante ist <code>VARIANT-PRE-COMPILE</code>, <code>Post-Build Variant Support</code> ist deaktiviert (<code>false</code>).\n</li><li><strong>Container (<code>MemIfGeneral: EcucParamConfContainerDef</code>)</strong>: Über die Kompositionsbeziehung <code>+container</code> (Multiplizität 1) dem Modul zugeordnet. Enthält allgemeine Konfigurationseinstellungen des Memory Abstraction Interface.\n</li><li><strong>Konfigurationsparameter</strong> (über Kompositionen <code>+parameter</code> an <code>MemIfGeneral</code> angebunden):\n<ul class=\"fig-list\"><li><code>MemIfDevErrorDetect: EcucBooleanParamDef</code>: Schalter für die Erkennung von Entwicklungsfehlern mit Defaultwert <code>false</code>.\n</li><li><code>MemIfNumberOfDevices: EcucIntegerParamDef</code>: Anzahl der adressierbaren Abstraction-Treiber (z. B. Fee/Ea) mit Wertebereich <code>min = 1</code> bis <code>max = 2</code>.\n</li><li><code>MemIfVersionInfoApi: EcucBooleanParamDef</code>: Aktivierung der Version-Information-API (<code>MemIf_GetVersionInfo</code>) mit Defaultwert <code>false</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell-Diagramm stellt die Abbildung keine dynamischen Laufzeit- oder Sequenzabläufe dar. Sie definiert ausschließlich die zur Generierungs- bzw. Vorkompilierungszeit (<code>VARIANT-PRE-COMPILE</code>) gültige Struktur der Konfigurationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Konfiguration des Moduls <code>MemIf</code>:</p>\n<ul class=\"fig-list\"><li>Die Konfiguration ist rein vorkompilierbar (<code>VARIANT-PRE-COMPILE</code>); Post-Build-Varianten sind unzulässig.\n</li><li>Der Container <code>MemIfGeneral</code> ist mit exakt einer Instanz zwingend erforderlich (<code>Multiplicity 1</code>).\n</li><li>Der Parameter <code>MemIfNumberOfDevices</code> limitiert die maximale Anzahl konfigurierbarer darunterliegender Speichertreiber streng auf minimal 1 und maximal 2 Geräte.\n</li><li><code>MemIfDevErrorDetect</code> und <code>MemIfVersionInfoApi</code> sind standardmäßig inaktiv (<code>defaultValue = false</code>).\n</li></ul>"}, {"id": "FIG-0316f64b685937be", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationslayout (ECUC Parameter Definition) kombiniert aus tabellarischer Moduldefinition und UML-Klassendiagramm für das BSW-Modul <code>MemIf</code> (Memory Abstraction Interface) gemäß Spezifikationselement <code>ECUC_MemIf_00025</code>. Das Diagramm definiert die statische Metamodell-Struktur des Moduls innerhalb des AUTOSAR-Konfigurationsframeworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in eine tabellarische Metadaten-Übersicht und ein metamodellbasiertes Klassendiagramm:</p>\n<ul class=\"fig-list\"><li><strong>Moduldefinition (<code>MemIf: EcucModuleDef</code>)</strong>: Bildet den Wurzelknoten mit der Multiplizität 0..1 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Unterstützte Konfigurationsvariante ist <code>VARIANT-PRE-COMPILE</code>, <code>Post-Build Variant Support</code> ist deaktiviert (<code>false</code>).\n</li><li><strong>Container (<code>MemIfGeneral: EcucParamConfContainerDef</code>)</strong>: Über die Kompositionsbeziehung <code>+container</code> (Multiplizität 1) dem Modul zugeordnet. Enthält allgemeine Konfigurationseinstellungen des Memory Abstraction Interface.\n</li><li><strong>Konfigurationsparameter</strong> (über Kompositionen <code>+parameter</code> an <code>MemIfGeneral</code> angebunden):\n<ul class=\"fig-list\"><li><code>MemIfDevErrorDetect: EcucBooleanParamDef</code>: Schalter für die Erkennung von Entwicklungsfehlern mit Defaultwert <code>false</code>.\n</li><li><code>MemIfNumberOfDevices: EcucIntegerParamDef</code>: Anzahl der adressierbaren Abstraction-Treiber (z. B. Fee/Ea) mit Wertebereich <code>min = 1</code> bis <code>max = 2</code>.\n</li><li><code>MemIfVersionInfoApi: EcucBooleanParamDef</code>: Aktivierung der Version-Information-API (<code>MemIf_GetVersionInfo</code>) mit Defaultwert <code>false</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell-Diagramm stellt die Abbildung keine dynamischen Laufzeit- oder Sequenzabläufe dar. Sie definiert ausschließlich die zur Generierungs- bzw. Vorkompilierungszeit (<code>VARIANT-PRE-COMPILE</code>) gültige Struktur der Konfigurationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Konfiguration des Moduls <code>MemIf</code>:</p>\n<ul class=\"fig-list\"><li>Die Konfiguration ist rein vorkompilierbar (<code>VARIANT-PRE-COMPILE</code>); Post-Build-Varianten sind unzulässig.\n</li><li>Der Container <code>MemIfGeneral</code> ist mit exakt einer Instanz zwingend erforderlich (<code>Multiplicity 1</code>).\n</li><li>Der Parameter <code>MemIfNumberOfDevices</code> limitiert die maximale Anzahl konfigurierbarer darunterliegender Speichertreiber streng auf minimal 1 und maximal 2 Geräte.\n</li><li><code>MemIfDevErrorDetect</code> und <code>MemIfVersionInfoApi</code> sind standardmäßig inaktiv (<code>defaultValue = false</code>).\n</li></ul>"}, {"id": "FIG-355a680d2f95cd02", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationslayout (ECUC Parameter Definition) kombiniert aus tabellarischer Moduldefinition und UML-Klassendiagramm für das BSW-Modul <code>MemIf</code> (Memory Abstraction Interface) gemäß Spezifikationselement <code>[ECUC_MemIf_00025]</code>. Das Diagramm definiert die statische Metamodell-Struktur des Moduls innerhalb des AUTOSAR-Konfigurationsframeworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in eine tabellarische Metadaten-Übersicht und ein metamodellbasiertes Klassendiagramm:</p>\n<ul class=\"fig-list\"><li><strong>Moduldefinition (<code>MemIf: EcucModuleDef</code>)</strong>: Bildet den Wurzelknoten mit der Multiplizität 0..1 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Unterstützte Konfigurationsvariante ist <code>VARIANT-PRE-COMPILE</code>, <code>Post-Build Variant Support</code> ist deaktiviert (<code>false</code>).\n</li><li><strong>Container (<code>MemIfGeneral: EcucParamConfContainerDef</code>)</strong>: Über die Kompositionsbeziehung <code>+container</code> (Multiplizität 1) dem Modul zugeordnet. Enthält allgemeine Konfigurationseinstellungen des Memory Abstraction Interface.\n</li><li><strong>Konfigurationsparameter</strong> (über Kompositionen <code>+parameter</code> an <code>MemIfGeneral</code> angebunden):\n<ul class=\"fig-list\"><li><code>MemIfDevErrorDetect: EcucBooleanParamDef</code>: Schalter für die Erkennung von Entwicklungsfehlern mit Defaultwert <code>false</code>.\n</li><li><code>MemIfNumberOfDevices: EcucIntegerParamDef</code>: Anzahl der adressierbaren Abstraction-Treiber (z. B. Fee/Ea) mit Wertebereich <code>min = 1</code> bis <code>max = 2</code>.\n</li><li><code>MemIfVersionInfoApi: EcucBooleanParamDef</code>: Aktivierung der Version-Information-API (<code>MemIf_GetVersionInfo</code>) mit Defaultwert <code>false</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell-Diagramm stellt die Abbildung keine dynamischen Laufzeit- oder Sequenzabläufe dar. Sie definiert ausschließlich die zur Generierungs- bzw. Vorkompilierungszeit (<code>VARIANT-PRE-COMPILE</code>) gültige Struktur der Konfigurationsparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Konfiguration des Moduls <code>MemIf</code>:</p>\n<ul class=\"fig-list\"><li>Die Konfiguration ist rein vorkompilierbar (<code>VARIANT-PRE-COMPILE</code>); Post-Build-Varianten sind unzulässig.\n</li><li>Der Container <code>MemIfGeneral</code> ist mit exakt einer Instanz zwingend erforderlich (<code>Multiplicity 1</code>).\n</li><li>Der Parameter <code>MemIfNumberOfDevices</code> limitiert die maximale Anzahl konfigurierbarer darunterliegender Speichertreiber streng auf minimal 1 und maximal 2 Geräte.\n</li><li><code>MemIfDevErrorDetect</code> und <code>MemIfVersionInfoApi</code> sind standardmäßig inaktiv (<code>defaultValue = false</code>).\n</li></ul>"}], "trans": [{"from": "FIG-0f592005afa03dac", "to": "FIG-0316f64b685937be", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0316f64b685937be", "to": "FIG-355a680d2f95cd02", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Modultabellenkopf: Attributbezeichner <code>Module Description</code> zu <code>Description</code> verkürzt und SWS-Item-Identifikator <code>[ECUC_MemIf_00025]</code> in eckige Klammern gesetzt.\n</li><li>Tabellengestaltung: Typografie, Zeilenhöhen und Abstände der Spezifikationstabellen an ein aktualisiertes Dokumenten-Layout angepasst.\n</li></ul>"}]};
